// seed: tests/seed.talent.spec.ts
// Healed 2026-11-03 by autotest-writer (NOT run): route /profile?edit=details → /profile?edit=personal, explanations asserted,
// demo-talent-1 must be PUBLIC (#a904f9 «existing talents keep their choice»). Read-only: never clicks a radio, never saves.
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/talent.json') });

test.describe('Talent Edit Profile — saved onboarding data (existing talent, read-only)', () => {
  test('Edit Profile has the anonymous / public profile radios with explanations @desktop @prod-safe #1866b6 #a904f9', async ({ page }) => {
    // 1–2. /profile?edit=personal, tab «פרטים אישיים»
    await page.goto('/profile?edit=personal');
    const tab = page.getByRole('tab', { name: 'פרטים אישיים' });
    await expect(tab).toBeVisible();
    if ((await tab.getAttribute('aria-selected')) !== 'true') await tab.click();
    await expect(tab).toHaveAttribute('aria-selected', 'true');

    // 3. Radio group profile-visibility: 2 radios, exactly one checked — public for demo-talent-1
    const radios = page.locator('input[name="profile-visibility"]');
    await expect(radios).toHaveCount(2);
    await expect(page.locator('input[name="profile-visibility"]:checked')).toHaveCount(1);
    await expect(radios.and(page.locator('[value="public"]'))).toBeChecked();
    await expect(radios.and(page.locator('[value="anonymous"]'))).not.toBeChecked();

    // Each option has its own privacy explanation next to the label (#a904f9 p.3, §36 AC05)
    for (const [value, label] of [['anonymous', 'פרופיל אנונימי'], ['public', 'פרופיל גלוי']] as const) {
      const option = page.locator('label').filter({ has: page.locator(`input[name="profile-visibility"][value="${value}"]`) });
      await expect(option).toContainText(label);
      const text = (await option.innerText()).replace(label, '').trim();
      expect(text.length, `explanation next to «${label}»`).toBeGreaterThan(10);
    }
  });
});
